u8 ov80_02237B58(u8 challengeType, BOOL includePartnersMons);

int ov80_02237A70(u8 challengeType, int currentRound, int trainerOffset) {
    if (challengeType == 0) {
        int currentStreak = (currentRound * 7) + (trainerOffset + 1);

        if (currentStreak == 21) {
            return FRONTIER_TRAINER_CASTLE_VALET_DARACH_SILVER;
        } else if (currentStreak == 49) {
            return FRONTIER_TRAINER_CASTLE_VALET_DARACH_GOLD;
        }
    }

    if (currentRound >= (sizeof(ov80_0223D4D4) / sizeof(*(ov80_0223D4D4)))) {
        currentRound = (sizeof(ov80_0223D4D4) / sizeof(*(ov80_0223D4D4))) - 1;
    }

    int spread, min;
    if (trainerOffset == 7 - 1 || trainerOffset == (7 * 2) - 1) {
        spread = ov80_0223D4D4[currentRound].finalMax - ov80_0223D4D4[currentRound].finalMin;
        min = ov80_0223D4D4[currentRound].finalMin;
    } else {
        spread = ov80_0223D4D4[currentRound].normalMax - ov80_0223D4D4[currentRound].normalMin;
        min = ov80_0223D4D4[currentRound].normalMin;
    }

    return min + LCRandom() % spread;
}

void ov80_02237ADC(u8 challengeType, int currentRound, u16 trainerIDs[], u8 numTrainers) {
    int i = 0;
    do {
        trainerIDs[i] = ov80_02237A70(challengeType, currentRound, i);

        int j;
        for (j = 0; j < i; j++) {
            if (trainerIDs[j] == trainerIDs[i]) {
                break;
            }
        }

        if (j != i) {
            continue;
        }

        i++;
    } while (i < numTrainers);
}

